47	    @NotEmpty
48	    @Digits(fraction = 0, integer = 10)
49	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
50	    private String telephone;
51	
52	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
53	    private Set<Pet> pets;
54	
55	    public String getAddress() {
56	        return this.address;
57	    }
58	
59	    public void setAddress(String address) {
60	        this.address = address;
61	    }
62	
63	    public String getCity() {
64	        return this.city;
65	    }
66	
67	    public void setCity(String city) {
68	        this.city = city;
69	    }
70	
71	    public String getTelephone() {
72	        return this.telephone;
73	    }
74	
75	    public void setTelephone(String telephone) {
76	        this.telephone = telephone;
77	    }
78	
79	    protected Set<Pet> getPetsInternal() {
80	        if (this.pets == null) {
81	            this.pets = new HashSet<>();
82	        }
83	        return this.pets;
84	    }
85	
86	    protected void setPetsInternal(Set<Pet> pets) {
87	        this.pets = pets;
88	    }
89	
90	    public List<Pet> getPets() {
91	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
92	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
93	        return Collections.unmodifiableList(sortedPets);
94	    }
95	
96	    public void setPets(List<Pet> pets) {
97	        this.pets = new HashSet<>(pets);
98	    }
99	
100	    public void addPet(Pet pet) {
101	        getPetsInternal().add(pet);
102	        pet.setOwner(this);
103	    }
104	
105	    /**
106	     * Return the Pet with the given name, or null if none found for this Owner.
107	     *
108	     * @param name to test
109	     * @return true if pet name is already in use
110	     */
111	    public Pet getPet(String name) {
112	        return getPet(name, false);
113	    }
114	
115	    /**
116	     * Return the Pet with the given name, or null if none found for this Owner.
117	     *
118	     * @param name to test
119	     * @return true if pet name is already in use
120	     */
121	    public Pet getPet(String name, boolean ignoreNew) {
122	        name = name.toLowerCase();
123	        for (Pet pet : getPetsInternal()) {
124	            if (!ignoreNew || !pet.isNew()) {
125	                String compName = pet.getName();
126	                compName = compName.toLowerCase();
127	                if (compName.equals(name)) {
128	                    return pet;
129	                }
130	            }
131	        }
132	        return null;
133	    }
134	
135	    public Pet getPet(Integer petId) {
136	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
137	    }
138	
139	    @Override
140	    public String toString() {
141	        return new ToStringCreator(this)
142	
143	            .append("id", this.getId())
144	            .append("new", this.isNew())
145	            .append("lastName", this.getLastName())
146	            .append("firstName", this.getFirstName())
147	            .append("address", this.address)
148	            .append("city", this.city)
149	            .append("telephone", this.telephone)
150	            .toString();
151	    }
152	}
